<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
const props=defineProps<{node:string;clear:boolean;cao:boolean;backdrop:string}>(),emit=defineEmits<{complete:[]}>(),selected=ref(-1)
const points=computed(()=>props.cao?[{name:'望向船影',x:38,y:49,text:props.clear?'船侧草把在月下露了形，身后不见冲寨的队列。':'只能看见桅杆和船灯，雾后的究竟是谁，眼下还不能断定。'},{name:'看寨口弓阵',x:78,y:39,text:['C_shoot','C_recognize'].includes(props.node)?'一阵箭已经射出，弓手收弦听令。下一阵还放不放，要由你决定。':'弓弩已备，军士仍在等令。箭一发出去，便收不回来了。'},{name:'察外侧水道',x:57,y:65,text:'哨艇可沿这里探近；水线再外一段，寨内便照应不到。'}]:[{name:'望曹寨灯火',x:78,y:30,text:props.clear?'月光映出寨门与守军。没有雾遮掩，草把便难冒充真人。':'灯影断断续续，寨门藏在雾后。看不清，不等于没人守。'},{name:'看近处船舷',x:25,y:67,text:'草把在船外，军士留在舱内；操舟的通道仍要畅通。'},{name:'找回船水道',x:59,y:55,text:'留在外侧，前船掉头时后船才有地方跟上。'}])
const source=computed(()=>selected.value<0?props.backdrop:`./v12/${selected.value===2?'look-waterway':props.cao?(selected.value===1?'look-bowline':props.clear?'look-clear-straw':'look-fog-boats'):(selected.value===1?'look-clear-straw':props.clear?'look-bowline':'look-fog-fort')}.webp`)
const display=ref(props.backdrop),loading=ref(false);let ticket=0
watch(source,async value=>{const id=++ticket;loading.value=true;const im=new Image();im.src=value;try{await im.decode();if(id===ticket)display.value=value}catch{}finally{if(id===ticket)loading.value=false}})
onBeforeUnmount(()=>ticket++)
</script>
<template><section class="observation-stage"><Transition name="detail-dissolve"><img :key="display" class="observation-plate" :src="display" alt="江面观察画面"/></Transition><div class="observe-shade"></div><div v-if="!clear&&selected>=1" class="detail-fog"></div><header><span>眼前能看见什么</span><h2>{{cao?'登台望江':'起行之前，先看江面'}}</h2><p>点景物靠近看；返回全景后，再作安排。</p></header><template v-if="selected<0"><button class="observe-target" v-for="(p,i) in points" :key="p.name" :style="{left:p.x+'%',top:p.y+'%'}" @click="selected=i"><i></i>{{p.name}}</button></template><div class="observe-detail" v-else><h3>{{points[selected].name}}</h3><p>{{points[selected].text}}</p><small v-if="loading">正在移近……</small><button @click="selected=-1">退回全景</button></div><button class="gold observe-return" @click="emit('complete')">看过了，作出安排</button></section></template>
<style scoped>.observation-stage{position:absolute;inset:0;overflow:hidden;background:#081723}.observation-plate{width:100%;height:100%;object-fit:cover;transition:transform 1.1s cubic-bezier(.2,.65,.2,1)}.observe-shade{position:absolute;inset:0;background:linear-gradient(180deg,#06101bc9,transparent 45%,#06101b66)}header{position:absolute;top:10%;left:6%;max-width:460px}header span{color:#cfb57e;font-size:12px;letter-spacing:.2em}header h2{font:35px SimSun;color:#efdfbf}header p{color:#c5d6de;font-size:14px}.observe-target{position:absolute;transform:translate(-50%,-50%);display:flex;gap:9px;align-items:center;padding:14px;background:#092131c9!important;border-bottom:1px solid #d3b27b!important;color:#f5e6bf!important}.observe-target i{width:8px;height:8px;border-radius:50%;background:#ffd385;box-shadow:0 0 18px #e6bb6b}.observe-detail{position:absolute;left:6%;bottom:13%;max-width:440px;padding:20px 30px;background:#e5d6b8;color:#24363d;border-left:4px solid #9a6941;box-shadow:0 10px 40px #0006}.observe-detail h3{font:24px SimSun;margin:0 0 12px}.observe-detail p{line-height:1.8}.observe-detail button{border-bottom:1px solid #6e573c;padding:10px}.observe-return{position:absolute;bottom:5%;right:6%}@media(prefers-reduced-motion:reduce){.observation-plate{transition:none}}@media(max-width:650px){header h2{font-size:26px}.observe-target{font-size:12px;padding:10px}.observe-detail{left:5%;right:5%;bottom:18%;padding:15px}}
</style>

<style scoped>.detail-fog{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#9daeb766,transparent 70%),radial-gradient(ellipse at 20% 10%,#afbcc879,transparent 60%);backdrop-filter:contrast(.87) saturate(.75)}</style>
